    "case.acc.n" to SkillStyleContent(rule=null, table=null, scene=null, nativeParallel=listOf(NativeParallelPair("Вижу моё старое окно.", "Widzę moje stare okno.", "Средний род в винительном падеже не меняется ни в русском, ни в польском: «окно» и okno остаются в исходной форме.", true, emptyList())), examples=listOf("Mam nowe okno.", "Widzę małe dziecko."), why="Средний род — самый простой случай: винительный падеж внешне совпадает с именительным, потому что у среднего рода в обоих языках нет отдельного окончания для этой роли."),
    "case.acc.f" to SkillStyleContent(rule=null, table=null, scene=null, nativeParallel=listOf(NativeParallelPair("Вижу мою хорошую жену.", "Widzę moją dobrą żonę.", "В обоих языках женский род на -a/-а получает окончание -ę/-у в винительном: żona→żonę, жена→жену; прилагательное меняется вместе с существительным.", true, emptyList())), examples=listOf("Mam nową książkę.", "Lubię moją siostrę."), why="Прямой объект после глаголов действия (widzę, mam, lubię) обычно стоит в винительном; у женского рода на -a это всегда -ę, как и в русском -а→-у."),
    "case.acc.m" to SkillStyleContent(rule=null, table=null, scene=null, nativeParallel=listOf(NativeParallelPair("Вижу мужа.", "Widzę męża.", "Одушевлённые существительные мужского рода в винительном совпадают с родительным — это работает одинаково в русском и польском.", true, emptyList()), NativeParallelPair("Вижу дом.", "Widzę dom.", "Неодушевлённые существительные мужского рода в винительном совпадают с именительным — тоже как в русском.", true, emptyList())), examples=listOf("Widzę psa.", "Widzę samochód."), why="Мужской род различает живое и неживое в винительном падеже — это не польская особенность, а общее славянское правило, знакомое из русского."),
    "case.gen.neg" to SkillStyleContent(rule=null, table=null, scene=null, nativeParallel=listOf(NativeParallelPair("Не вижу жену.", "Nie widzę żony.", "В русском при отрицании падеж не меняется (живы оба варианта — «жену»/«жены»); в польском после nie обязателен Dopełniacz.", false, emptyList()), NativeParallelPair("Не вижу книгу.", "Nie widzę książki.", "Тот же сдвиг у неодушевлённого объекта — родительный обязателен без вариантов.", false, emptyList())), examples=listOf("Nie mam czasu.", "Nie widzę żadnego problemu."), why="В польском отрицание всегда переводит прямое дополнение в родительный падеж; в русском это необязательно и звучит скорее книжно."),
    "case.inst" to SkillStyleContent(rule=null, table=null, scene=null, nativeParallel=listOf(NativeParallelPair("Иду с женой.", "Idę z żoną.", "После «с»/z в значении совместности оба языка требуют творительного падежа.", true, emptyList()), NativeParallelPair("Я программист.", "Jestem programistą.", "В польском профессия при być всегда в творительном; в разговорном русском связку «быть» обычно пропускают и говорят в именительном («Я программист»), творительный нужен только с «являюсь».", false, emptyList())), examples=listOf("Rozmawiam z kolegą.", "Jestem nauczycielem."), why="Творительный после z/с — обычное дело в обоих языках; а вот профессия при глаголе «быть» — разные привычки: поляки всегда используют творительный, русские обычно говорят в именительном без связки."),
    "case.loc" to SkillStyleContent(rule=null, table=null, scene=null, nativeParallel=listOf(NativeParallelPair("Говорю о жене.", "Mówię o żonie.", "После «о» оба языка используют падеж, обозначающий тему разговора (в русском предложный, в польском Miejscownik) — сама логика конструкции совпадает.", true, emptyList())), examples=listOf("Myślę o tobie.", "Czytam o historii."), why="Предлог о/o вводит тему и требует особого падежа — в русском предложный, в польском Miejscownik; окончания разные, но роль в предложении одна и та же."),
    "case.dat" to SkillStyleContent(rule=null, table=null, scene=null, nativeParallel=listOf(NativeParallelPair("Даю жене подарок.", "Daję żonie prezent.", "Дательный падеж получателя действия — совпадает в обоих языках.", true, emptyList()), NativeParallelPair("Помогаю жене.", "Pomagam żonie.", "Глагол «помогать»/pomagać управляет дательным падежом в обоих языках.", true, emptyList())), examples=listOf("Mówię ci prawdę.", "Dziękuję nauczycielowi."), why="Celownik/дательный отвечает на «кому?» и работает одинаково с глаголами давания и помощи в обоих языках."),
    "agreement.my" to SkillStyleContent(rule=null, table=null, scene=null, nativeParallel=listOf(NativeParallelPair("Вижу его жену.", "Widzę jego żonę.", "«его» и jego не склоняются в обоих языках — это готовая форма для любого падежа и рода.", true, emptyList()), NativeParallelPair("Вижу мою жену.", "Widzę moją żonę.", "«моя»/moja склоняется по роду и падежу существительного одинаково в обоих языках.", true, emptyList())), examples=listOf("To jest jej dom.", "Widzę ich dzieci."), why="jego/jej/ich (его/её/их) не склоняются, потому что это застывшие формы местоимения — точно как в русском; а mój/twój/nasz/wasz согласуются с существительным, как «мой/твой/наш/ваш»."),
    "verb.present" to SkillStyleContent(rule=null, table=null, scene=null, nativeParallel=listOf(NativeParallelPair("Он идёт.", "On idzie.", "В настоящем времени оба языка спрягают глагол по лицу и числу: 3-е лицо единственного числа — идёт/idzie, окончание показывает лицо одинаково в обоих языках.", true, emptyList())), examples=listOf("Idzie do szkoły.", "Idą do pracy."), why="Формы настоящего времени различаются по лицу в обоих языках, но польский чаще опускает местоимение — окончание глагола само называет действующее лицо."),
    "verb.past" to SkillStyleContent(rule=null, table=null, scene=null, nativeParallel=listOf(NativeParallelPair("Она шла.", "Szła.", "Прошедшее время согласуется с родом подлежащего в обоих языках — «шла» и szła оба показывают женский род.", true, emptyList()), NativeParallelPair("Он шёл.", "Szedł.", "Мужской род прошедшего времени тоже совпадает — «шёл» и szedł; лицо (он) в обоих языках выражено отдельным словом, сам глагол лица не называет.", true, emptyList())), examples=listOf("Szedł do pracy.", "Szła do szkoły."), why="Прошедшее время в обоих языках зависит от рода — это общая славянская черта; а вот лицо (я/ты/он) в польском показывает сам глагол, а в русском — только отдельное местоимение."),
    "verb.future" to SkillStyleContent(rule=null, table=null, scene=null, nativeParallel=listOf(NativeParallelPair("Буду идти.", "Będę iść.", "Общая модель будущего несовершенного вида: буду/będę + инфинитив — сохраняется независимо от лица.", true, emptyList()), NativeParallelPair("Он будет идти.", "On będzie iść.", "Именно эту модель тренирует упражнение: 3-е лицо, будущее несовершенного вида — będzie + iść.", true, emptyList())), examples=listOf("Będziesz iść.", "Będziemy iść."), why="У будущего времени в обоих языках два способа: составное для незавершённого действия (буду/będę + инфинитив) и простая форма для завершённого результата (сделаю/zrobię) — структура полностью совпадает."),
    "aspect" to SkillStyleContent(rule=null, table=null, scene=null, nativeParallel=listOf(NativeParallelPair("Я делал (не закончил).", "Robiłem.", "Несовершенный вид описывает процесс без гарантии завершения — одинаково в обоих языках.", true, emptyList()), NativeParallelPair("Я сделал (готово).", "Zrobiłem.", "Совершенный вид подчёркивает завершённый результат — то же противопоставление, что в русской паре «сделал» против «делал».", true, emptyList())), examples=listOf("Czytałem książkę.", "Przeczytałem książkę."), why="Пара несовершенный/совершенный вид (robić/zrobić) — это то же противопоставление процесса и результата, что в русской паре делать/сделать; понятие переносится почти без изменений."),
    "pronouns" to SkillStyleContent(rule=null, table=null, scene=null, nativeParallel=listOf(NativeParallelPair("Знаю её.", "Znam ją.", "Личное местоимение склоняется по падежу в обоих языках, хотя конкретные формы разные.", true, emptyList()), NativeParallelPair("Говорю о ней.", "Mówię o niej.", "После предлога оба языка добавляют дополнительный звук к местоимению: русское «н-» (о ней, с ней) и польское «ni-» (o niej, z nią) появляются в одной и той же позиции.", true, emptyList())), examples=listOf("Idę z nią.", "Pomagam mu."), why="Местоимения склоняются по падежу в обоих языках; в косвенных падежах после предлогов и русский, и польский вставляют один и тот же дополнительный звук (н-/ni-) — это не совпадение, а общее наследие."),
    "mixed" to SkillStyleContent(rule=null, table=null, scene=null, nativeParallel=listOf(NativeParallelPair("Ты не видел мою жену.", "Nie widziałeś mojej żony.", "В русском отрицание не всегда меняет падеж — винительный «жену» тоже допустим (родительный «жены» звучит книжнее); в польском после nie родительный обязателен всегда, без вариантов.", false, emptyList())), examples=listOf("Nie robiłem tego wczoraj.", "Nie widziałem jej domu."), why="Смешанное задание складывает несколько правил сразу: время, отрицание и падеж работают как отдельные, независимые условия — проверяй их по одному, а не все сразу."),
    "sentence.question" to SkillStyleContent(rule=null, table=null, scene=null, nativeParallel=listOf(NativeParallelPair("Ты видишь мою жену?", "Czy widzisz moją żonę?", "В русском общий вопрос обычно образуется только интонацией (падежи и порядок слов не меняются); в польском для этого есть отдельное слово czy в начале предложения.", false, emptyList())), examples=listOf("Czy masz czas?", "Czy on tu jest?"), why="В русском вопрос без вопросительного слова опирается на интонацию (изредка — книжную частицу «ли» после глагола); в польском для этого есть отдельное слово czy, которое всегда ставится в начале предложения."),
    "sentence.plural" to SkillStyleContent(rule=null, table=null, scene=null, nativeParallel=listOf(NativeParallelPair("Мои коллеги. Мои книги.", "Moi koledzy. Moje książki.", "В русском множественное число прилагательного/местоимения одно для всех родов и групп («мои» и там, и там); в польском мужская личная группа (koledzy) получает особую форму (moi), отличную от остальных существительных (moje książki).", false, emptyList())), examples=listOf("Moi bracia.", "Moje siostry."), why="Главная сложность множественного числа в польском — категория «мужская личная группа» (люди мужского пола), у которой особые формы прилагательных, местоимений и глаголов; в русском такого разделения во множественном числе нет."),

)
